                if(!if_opcodereg[3]) begin //AR register
                    if(if_opcodereg[0]) reg_arp_set = YES;
                    else                reg_arp_rst = YES;
                end
            end

            `ifdef IKA32010_DISASSEMBLY 
                disasm_type2("DMOV", if_opcodereg, if_pc, 0, 0);
            `endif
        end

